package com.bananalab.lite;
import android.content.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Own 64-feature online classifier. Learns only from explicit user feedback, never its own guesses. */
final class PlannerExperience{
 static final int D=64;static volatile JSONObject model;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-planner-experience",0);}
 static String key(JSONObject data)throws Exception{return JavaMethodEditor.hash(data.toString());}
 static float[] features(String input){float[] x=new float[D];for(String word:ChatLanguage.normalize(input).split(" "))if(!word.isEmpty())x[(word.hashCode()&0x7fffffff)%(D-1)]+=1;float norm=0;for(float v:x)norm+=v*v;if(norm>0){norm=(float)Math.sqrt(norm);for(int i=0;i<D-1;i++)x[i]/=norm;}x[D-1]=1;return x;}
 static float[][] weights(JSONObject stored,int n)throws Exception{float[][] w=new float[n][D];JSONArray rows=stored.getJSONArray("weights");if(rows.length()!=n)throw new IllegalArgumentException("Modelo incompatible.");for(int i=0;i<n;i++){JSONArray row=rows.getJSONArray(i);if(row.length()!=D)throw new IllegalArgumentException("Dimensión del modelo inválida.");for(int j=0;j<D;j++){float v=(float)row.getDouble(j);if(Float.isNaN(v)||Float.isInfinite(v)||Math.abs(v)>100)throw new IllegalArgumentException("Peso inválido.");w[i][j]=v;}}return w;}
 static float[] scores(float[][] w,String input){float[] x=features(input),s=new float[w.length];for(int i=0;i<w.length;i++)for(int j=0;j<D;j++)s[i]+=w[i][j]*x[j];return s;}
 static float[] scores(JSONObject data,String input)throws Exception{JSONObject saved=model;int n=data.getJSONArray("rules").length();if(saved==null||!key(data).equals(saved.optString("rulesHash")))return new float[n];return scores(weights(saved,n),input);}
 static void restore(Context c){try{String raw=prefs(c).getString("model","");model=raw.isEmpty()?null:new JSONObject(raw);if(model!=null)weights(model,model.getJSONArray("weights").length());}catch(Exception e){model=null;prefs(c).edit().putString("error","No cargué el aprendizaje; uso las recetas sin pesos aprendidos.").apply();}}
 static void record(Context c,String command,BananaEngine.Result out)throws Exception{String[] r=PlannerDispatch.receipt.get();PlannerDispatch.receipt.remove();if(r!=null&&out.changed&&out.scene!=null){JSONObject last=new JSONObject().put("input",r[0]).put("rule",r[1]).put("rules",new JSONObject(r[2])).put("sceneHash",JavaMethodEditor.hash(out.scene.json().toString()));if(!prefs(c).edit().putString("last",last.toString()).commit())throw new java.io.IOException("No pude guardar el caso del planificador.");}}
 static JSONObject train(JSONObject data,JSONArray cases)throws Exception{int n=data.getJSONArray("rules").length();float[][] w=new float[n][D];for(int epoch=0;epoch<40;epoch++)for(int row=0;row<cases.length();row++){JSONObject example=cases.getJSONObject(row);if(!example.getString("rulesHash").equals(key(data)))continue;String input=example.getString("input"),label=example.getString("label");float[] x=features(input),scores=scores(w,input);JSONArray rules=data.getJSONArray("rules");for(int i=0;i<n;i++){JSONObject rule=rules.getJSONObject(i);if(!Pattern.matches(PlannerContract.pattern(rule.getString("phrase")),input))continue;boolean wanted=label.equals(rule.getString("id"));float target=wanted?2f:-2f;float error=target-scores[i];for(int j=0;j<D;j++)w[i][j]+=.08f*error*x[j];}}int count=0;for(int i=0;i<cases.length();i++){JSONObject example=cases.getJSONObject(i);if(!example.getString("rulesHash").equals(key(data)))continue;String[] got=PlannerContract.expected(data,example.getString("input"),scores(w,example.getString("input")));String actual=got==null?"":got[0];if(!actual.equals(example.getString("label")))throw new IllegalArgumentException("La actualización no retuvo todos los casos confirmados; conservé el modelo anterior.");count++;}JSONArray matrix=new JSONArray();for(float[] row:w)matrix.put(new JSONArray(row));return new JSONObject().put("rulesHash",key(data)).put("weights",matrix).put("retained",count).put("features",D);}
 static synchronized String feedback(Context c,boolean good)throws Exception{String raw=prefs(c).getString("last","");if(raw.isEmpty())return "Primero usá una receta del planificador. No tomo una respuesta inventada como un ejemplo correcto.";JSONObject last=new JSONObject(raw);SceneDraft current=MobileCore.scene(c);if(current==null||!JavaMethodEditor.hash(current.json().toString()).equals(last.getString("sceneHash")))return "La escena cambió desde ese plan. Probá la receta otra vez antes de evaluarla.";JSONObject data=last.getJSONObject("rules");JSONArray old=new JSONArray(prefs(c).getString("cases","[]")),next=new JSONArray();String hash=key(data);for(int i=Math.max(0,old.length()-31);i<old.length();i++){JSONObject example=old.getJSONObject(i);if(!(example.getString("rulesHash").equals(hash)&&example.getString("input").equals(last.getString("input"))))next.put(example);}next.put(new JSONObject().put("rulesHash",hash).put("input",last.getString("input")).put("label",good?last.getString("rule"):"").put("source","user"));JSONObject candidate=prefs(c).getBoolean("auto",true)?train(data,next):null;SharedPreferences.Editor edit=prefs(c).edit().putString("cases",next.toString()).remove("last");if(candidate!=null)edit.putString("backupCases",old.toString()).putString("backup",prefs(c).getString("model","")).putString("model",candidate.toString()).putInt("revision",prefs(c).getInt("revision",0)+1);if(!edit.commit())throw new java.io.IOException("No pude guardar el aprendizaje.");if(candidate!=null)model=candidate;return candidate==null?"Guardé tu evaluación. El aprendizaje automático está pausado.":"Aprendí de tu evaluación y ajusté los pesos propios del selector. Retuve "+candidate.getInt("retained")+" casos confirmados. Son pruebas de retención, no una evaluación independiente de inteligencia general.";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(!q.matches("ese plan esta bien|ese plan esta mal|estado aprendizaje planificador|pausa aprendizaje planificador|activa aprendizaje planificador|deshace aprendizaje planificador"))return null;try{String text;if(q.startsWith("ese plan"))text=feedback(c,q.endsWith("bien"));else if(q.startsWith("pausa")||q.startsWith("activa")){prefs(c).edit().putBoolean("auto",q.startsWith("activa")).commit();text=q.startsWith("activa")?"El selector se entrenará automáticamente al evaluar una receta.":"Pausé el entrenamiento automático; se conservan los pesos actuales.";}else if(q.startsWith("deshace")){if(!prefs(c).contains("backup"))return MobileCore.say(c,"No hay pesos anteriores para recuperar.","app_ajuste");String backup=prefs(c).getString("backup","");if(!prefs(c).edit().putString("model",backup).putString("cases",prefs(c).getString("backupCases","[]")).remove("backup").remove("backupCases").commit())throw new java.io.IOException("No pude recuperar el aprendizaje.");restore(c);text="Recuperé los pesos y ejemplos anteriores.";}else text="Aprendizaje del planificador · revisión "+prefs(c).getInt("revision",0)+"\nAutoentrenamiento al recibir tu evaluación: "+prefs(c).getBoolean("auto",true)+"\nEjemplos: "+new JSONArray(prefs(c).getString("cases","[]")).length()+" · 64 características propias por receta.\nSólo aprende a seleccionar o rechazar recetas existentes. No inventa objetivos, código arbitrario ni conocimientos verificados por sí mismo.\nEvaluá después de probar una receta: ‘ese plan está bien’ / ‘ese plan está mal’.";return MobileCore.say(c,text,"app_ajuste");}catch(Exception e){return MobileCore.say(c,"Conservé el aprendizaje activo: "+AndroidRepair.summary(e),"app_ajuste");}}
}
